declare(strict_types=1);

namespace Schoolbox\Config\API;

use Alaress\Module\Cache\Rebuilder;
use Alaress\Web\Controller\ConfigController;
use Crell\ApiProblem\ApiProblem;
use Psr\SimpleCache\CacheInterface;
use Schoolbox\Admin\Settings\FieldStrategyFactory;
use Schoolbox\API\Token\JwtParser\InstanceRegistryIssued;
use Schoolbox\Application\Exception\Exception as SchoolboxException;
use Schoolbox\Config\Config;
use Schoolbox\Config\ConfigMapper;
use Schoolbox\Mapper\Exception;

class Controller extends ConfigController
{
    /**
     * Controller constructor.
     *
     * @param ConfigMapper $configMapper
     * @param FieldStrategyFactory $fieldStrategyFactory
     * @param Rebuilder $rebuilder
     * @param CacheInterface $oidcCache
     * @param InstanceRegistryIssued $jwtParser
     */
    public function __construct(
        ConfigMapper $configMapper,
        FieldStrategyFactory $fieldStrategyFactory,
        Rebuilder $rebuilder,
        CacheInterface $oidcCache,
        private readonly InstanceRegistryIssued $jwtParser
    ) {
        parent::__construct($configMapper, $fieldStrategyFactory, $rebuilder, $oidcCache);
    }


    /**
     * Returns config object by name
     *
     * @param Config $config
     * @api GET /api/config/{configName}
     */
    public function apiConfigGet(Config $config): void
    {
        // Check if user can access this config
        $serverParams = $this->request->getServerParams();
        if (!AuthorizationHelper::canAccessConfig($config, $serverParams, $this->jwtParser)) {
            throw new SchoolboxException('Config Does not Exist', 404, null, 404);
        }

        $this->response = $this->responseAsJson(AuthorizationHelper::configToArray($config));
    }

    /**
     * Updates a single config value
     *
     * @param Config $config
     * @api POST /api/config/{configName}
     */
    public function apiConfigPatch(Config $config): void
    {
        // Check if user can edit this config
        $serverParams = $this->request->getServerParams();
        if (!AuthorizationHelper::canEditConfig($config, $serverParams, $this->jwtParser)) {
            throw new SchoolboxException('Config Does not Exist', 404, null, 404);
        }

        $data = $this->request->getParsedBody();
        if (null === $data) {
            $problem = (new ApiProblem('Request BODY has an issue, it may be empty or malformed', 'Missing Argument'))
                ->setStatus(400)
                ->asArray();
            $this->response = $this->responseAsJson($problem)
                                   ->withStatus(400);
            return;
        }

        if (!isset($data['value'])) {
            $problem = (new ApiProblem("POST request must include 'value' field", 'Missing Argument'))
                ->setStatus(400)
                ->asArray();
            $this->response = $this->responseAsJson($problem)
                                   ->withStatus(400);
            return;
        }

        try {
            $this->updateConfig(
                [$config->getName() => $data['value']],
                $this->getConfigMapper()->getPredicateBuilder()->equals(ConfigMapper::COL_NAME, $config->getName()),
            );

            /* Re-fetch the config to get the updated value and ensure validation is applied, this might be acceptable so won't change the
             * updateConfig method to return the updated config, as it would require changing the existing method signature and potentially
             *  affect other parts of the codebase that use it.
             */
            $config = $this->getConfigMapper()->findOneByColumn(ConfigMapper::COL_NAME, $config->getName());
        } catch (\UnexpectedValueException $e) {
            $problem = (new ApiProblem('Validation error: ' . $e->getMessage(), 'Validation Failed'))
                ->setStatus(400)
                ->asArray();
            $this->response = $this->responseAsJson($problem)
                                   ->withStatus(400);
            return;
        } catch (Exception $e) {
            $problem = (new ApiProblem($e->getMessage()))
                ->setStatus(400)
                ->asArray();
            $this->response = $this->responseAsJson($problem)
                                   ->withStatus(400);
            return;
        }

        $this->response = $this->responseAsJson(AuthorizationHelper::configToArray($config));
    }

    /**
     * Updates multiple config values in bulk
     *
     * @api POST /api/config/bulk
     */
    public function apiConfigBulkPatch(): void
    {

        $data = $this->request->getParsedBody();
        if (null === $data) {
            $problem = (new ApiProblem('Request BODY has an issue, it may be empty or malformed'))
                ->setStatus(400)
                ->asArray();
            $this->response = $this->responseAsJson($problem)
                                   ->withStatus(400);
            return;
        }

        if (!isset($data['configs']) || !is_array($data['configs'])) {
            $problem = (new ApiProblem("POST request must include 'configs' array", 'Missing Argument'))
                ->setStatus(400)
                ->asArray();
            $this->response = $this->responseAsJson($problem)
                                   ->withStatus(400);
            return;
        }

        $results = [];
        $errors = [];

        foreach ($data['configs'] as $configData) {
            $result = [
                'name' => $configData['name'] ?? 'unknown',
                'status' => 'failed'
            ];

            if (!isset($configData['name']) || !isset($configData['value'])) {
                $errors[] = "Each config must have 'name' and 'value' fields";
                $result['error'] = "Each config must have 'name' and 'value' fields";
                continue;
            }
            try {
                $config = $this->getConfigMapper()->findOneByColumn(ConfigMapper::COL_NAME, $configData['name']);

                // Check if user can edit this config
                $serverParams = $this->request->getServerParams();
                if (!AuthorizationHelper::canEditConfig($config, $serverParams, $this->jwtParser)) {
                    $errors[] = "Config '{$configData['name']}' not found";
                    $result['error'] = "Config '{$configData['name']}' not found";
                    $results[] = $result;
                    continue;
                }

                try {
                    $this->updateConfig(
                        [$config->getName() => $configData['value']],
                        $this->getConfigMapper()->getPredicateBuilder()->equals(ConfigMapper::COL_NAME, $config->getName()),
                    );

                    /* Re-fetch the config to get the updated value and ensure validation is applied, this might be acceptable so won't change the
                     * updateConfig method to return the updated config, as it would require changing the existing method signature and potentially
                     *  affect other parts of the codebase that use it.
                     */
                    $config = $this->getConfigMapper()->findOneByColumn(ConfigMapper::COL_NAME, $config->getName());
                } catch (\UnexpectedValueException $e) {
                    $errors[] = "Validation error for config '{$configData['name']}': " . $e->getMessage();
                    $result['error'] = "Validation error for config '{$configData['name']}': " . $e->getMessage();
                    $results[] = $result;
                    continue;
                }

                $result = AuthorizationHelper::configToArray($config);
                $result['status'] = 'success';
            } catch (\Schoolbox\Mapper\Exception $e) {
                $errors[] = "Config '{$configData['name']}' not found";
                $result['error'] = "Config '{$configData['name']}' not found";
            }
            $results[] = $result;
        }
        $successful = array_filter($results, function ($result) {
            return $result['status'] === 'success';
        });

        $output = [
            'results' => $results,
            'errors' => $errors,
            'total_processed' => count($data['configs']),
            'successful' => count($successful),
            'failed' => count($errors)
        ];

        $this->response = $this->responseAsJson($output);
    }

    /**
     * Returns site_package config value without authentication
     *
     * @api GET /api/config/public/site-package
     */
    public function apiSitePackageGet(): void
    {
        try {
            $config = $this->getConfigMapper()->findOneByColumn(ConfigMapper::COL_NAME, ConfigMapper::NAME_SITE_PACKAGE);

            // Return only the value for this specific endpoint
            $this->response = $this->responseAsJson([
                'name' => ConfigMapper::NAME_SITE_PACKAGE,
                'value' => $config->getValue()
            ]);
        } catch (\Schoolbox\Mapper\Exception $e) {
            throw new SchoolboxException('Config Does not Exist', 404, null, 404);
        }
    }
}
